{"path": "creative_intent.json", "content": "{
  "user_need": "警察男主绑定\"犯罪预警系统\"，能在凶手额头看到倒计时。他发现未婚妻（法医）额头显示\"将在今晚23:00杀害你\"。系统提示\"不可更改\"。他必须在12小时内破解这个\"未来命案\"，同时不能让她发现他在防备她。随着调查，他发现她杀他的动机是为了阻止他去救一个会导致更大灾难的证人（D20为理想牺牲）。12万字，高密度悬疑。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["牺牲", "破解", "调查", "阻止", "献祭"],
    "scene_elements": ["犯罪预警系统", "刑警", "法医", "12小时倒计时", "未来命案", "城市灾难"],
    "relationship_tension": ["未婚妻将杀害男主", "男主需防备未婚妻但不能暴露", "两人为公共利益被迫站在对立面"],
    "user_preferences": {
      "desired_emotion": "高密度烧脑悬疑、宿命感、理想牺牲的虐感",
      "forbidden": ["降智情节", "强行HE", "无关感情支线"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D20",
    "x_axis_mode_name": "为理想牺牲",
    "y_axis_tags": ["系统流", "刑侦悬疑", "规则怪谈"],
    "reaction_strength": "✷",
    "tension_stars": 5,
    "forbidden_elements": ["降智情节", "强行HE", "无关感情支线"],
    "x_axis_display": "男主未婚妻为阻止更大灾难发生，甘愿背负杀人犯罪名杀死爱人，两人都为公共利益牺牲个人情感",
    "y_axis_combination_effect": "犯罪预警系统的硬规则（不可更改未来）是核心解谜边界，刑侦调查推进线索，规则怪谈属性强化宿命感与逻辑解谜的烧脑感",
    "reaction_formula": "固定规则下的理想献祭 × 12小时倒计时解谜 = 高密度烧脑悬疑",
    "platform_fit": ["起点", "豆瓣阅读", "知乎盐选"]
  },
  "one_sentence_synopsis": "刑警陆沉绑定犯罪预警系统，发现法医未婚妻将在12小时后杀他，被迫在规则内破解这场宿命命案。"
}"}

