{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陆沉",
      "role": "protagonist",
      "identity": "市刑侦支队重案组组长",
      "traits": ["冷静理智", "观察力敏锐", "责任感极强", "原则性突出"],
      "overt_motivation": "12小时内破解自己将被未婚妻杀害的预言，避免死亡同时阻止潜在灾难",
      "covert_motivation": "保护苏晚，不让她背负杀人犯的罪名，守护两人的未来",
      "secret_fear": "被迫亲手将苏晚绳之以法，或是因自己的选择导致无数平民死亡",
      "misperception_of_other": "最初以为苏晚是被胁迫或产生误会才要杀自己，不知道她是为了公共利益主动做出的选择",
      "hidden_connection": "三年前苏晚刚入职时曾被嫌疑人报复，是陆沉冒死救了她，苏晚一直记在心里从未说破"
    },
    {
      "name": "苏晚",
      "role": "deuteragonist",
      "identity": "市公安局法医中心主检法医师，陆沉的未婚妻",
      "traits": ["逻辑缜密", "外冷内热", "信仰坚定", "执行力极强"],
      "overt_motivation": "在今晚23点准时杀死陆沉，阻止他去营救证人林小艾",
      "covert_motivation": "保护陆沉的名誉，不让他因为救证人而成为导致地铁爆炸案的罪人，独自承担所有罪责",
      "secret_fear": "陆沉提前发现她的计划，执意去救林小艾，最终导致爆炸发生，全城死伤惨重",
      "misperception_of_other": "不知道陆沉已经通过犯罪预警系统看到了她额头的倒计时，以为自己的计划完全保密",
      "hidden_connection": "她的父亲当年也是刑警，为了阻止爆炸案牺牲，所以她比任何人都清楚灾难的代价"
    }
  ],
  "supporting_characters": [
    {
      "name": "赵国栋",
      "function": "助力",
      "identity": "市公安局局长",
      "description": "知道毒贩将要实施地铁爆炸案的核心机密，暗中给陆沉递线索，是陆沉最终能破局的关键"
    },
    {
      "name": "陈默",
      "function": "阻碍/反转点",
      "identity": "刑侦支队副队长，毒贩安插的内鬼",
      "description": "一直暗中给毒贩传递消息，想要同时杀死陆沉和证人林小艾，掩盖爆炸案的计划"
    },
    {
      "name": "林小艾",
      "function": "反转点",
      "identity": "毒贩团伙的前会计，爆炸案的唯一证人",
      "description": "掌握毒贩放置炸弹的具体位置，她的证词是阻止爆炸的唯一证据，但她的出现也会触发毒贩的引爆指令"
    }
  ],
  "relationship_dynamics": "陆沉与苏晚是相恋五年即将结婚的恋人，却因为犯罪预警系统的一个预言被迫站在对立面，两人都为了守护公众利益和保护对方，选择独自承担痛苦，彼此试探却又不敢暴露真心，最终走向必然的献祭结局。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（共6章，约3万字，占总篇幅25%）：建立犯罪预警系统的世界观，展示陆沉与苏晚的日常工作和感情状态，核心冲突爆发——陆沉在苏晚额头看到杀害自己的倒计时，系统提示不可更改，陆沉开始暗中调查，同时需掩饰防备心理避免被苏晚察觉。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红色倒计时",
        "core_event": "陆沉结束连环杀人案抓捕行动回到警局，在走廊碰到刚做完尸检的苏晚，第一次看到她额头浮现的红色数字倒计时，系统弹出提示：凶手苏晚，将于今日23:00杀害你，事件不可更改。",
        "emotional_tone": "震惊、荒诞、不可置信",
        "key_scenes": ["警局走廊碰面场景", "系统面板弹出场景", "陆沉掩饰情绪和苏晚日常对话场景"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "死亡预言",
        "core_event": "陆沉回忆三个月前绑定犯罪预警系统的过程，系统此前的17次预言全部应验，他通过之前的案件验证系统的准确性，确认这次的预言不是幻觉。",
        "emotional_tone": "怀疑、焦虑、冰冷",
        "key_scenes": ["陆沉回忆系统绑定场景", "翻查过往案件记录验证系统准确性场景", "办公室独处思考场景"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "异常痕迹",
        "core_event": "陆沉秘密调查苏晚近两周的行踪和经手的案件，发现她私下一直在跟进“715毒贩团伙”案，甚至越权查看了涉密的证人保护信息，行为明显异常。",
        "emotional_tone": "紧张、疑惑、不安",
        "key_scenes": ["陆沉违规查询内部系统记录场景", "找下属旁敲侧击询问苏晚的动向场景", "发现苏晚藏起来的案件资料场景"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "餐桌试探",
        "core_event": "两人回到同居的家准备婚礼请柬，苏晚旁敲侧击询问陆沉当天晚上和第二天的行程，陆沉撒谎掩饰，两人看似日常的对话下暗流涌动，陆沉确认苏晚确实在策划什么。",
        "emotional_tone": "压抑、微妙、各怀心事",
        "key_scenes": ["两人一起做饭场景", "餐桌对话试探场景", "陆沉看着苏晚的倒计时默默计算剩余时间场景"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "爆炸预警",
        "core_event": "陆沉接到赵局的秘密通知，线人传来消息，715毒贩团伙准备在今晚23:30引爆地铁1号线的炸弹，制造恐怖袭击，陆沉瞬间将这件事和苏晚的倒计时联系起来。",
        "emotional_tone": "凝重、警觉、豁然开朗",
        "key_scenes": ["赵局秘密谈话场景", "陆沉梳理时间线场景", "第一次将爆炸案和苏晚的杀人计划关联场景"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "证人林小艾",
        "core_event": "陆沉查到苏晚最近一直在秘密寻找毒贩团伙的前会计林小艾的下落，而林小艾正是爆炸案的唯一证人，只要警方找到她，就能拿到炸弹的具体位置。",
        "emotional_tone": "困惑、线索交汇、充满悬念",
        "key_scenes": ["查到林小艾的身份信息场景", "陆沉推演苏晚的动机场景", "发现苏晚在跟踪林小艾行踪场景"]
      }
    ],
    "turning_point": "陆沉确认苏晚要杀他的动机，与即将发生的地铁爆炸案有直接关联，她的行为不是私人恩怨，而是和公共安全相关。"
  },
  "act_two": {
    "description": "第二幕（共12章，约6万字，占总篇幅50%）：陆沉一边继续掩饰自己的防备心理，一边深入调查爆炸案的全部细节，和苏晚展开高智商的互相试探，与藏在警局内部的内鬼陈默斗智斗勇，最终得知苏晚要杀他的全部真相。",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "内鬼阴影",
        "core_event": "陆沉调查林小艾下落的消息被泄露，他意识到警局内部有毒贩的内鬼，一边要防着苏晚，一边要排查内鬼，陷入腹背受敌的境地。",
        "emotional_tone": "紧绷、危险、步步为营",
        "key_scenes": ["陆沉的调查行动被泄露场景", "陈默主动过来询问案件进展试探陆沉场景", "陆沉第一次怀疑内鬼是陈默场景"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "规则边界",
        "core_event": "陆沉尝试用各种方式更改预言，比如申请调离当天的任务，故意把自己锁在警局审讯室，但是系统一直提示“事件不可更改”，他意识到自己无法逃避，只能在规则内寻找破局方法。",
        "emotional_tone": "绝望、宿命感、烧脑",
        "key_scenes": ["陆沉申请调离任务被驳回场景", "陆沉尝试自我关押测试系统场景", "系统多次弹出不可更改提示场景"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "死亡条件",
        "core_event": "陆沉找到之前的线人，拿到毒贩的行动计划：只要陆沉带队出现在营救林小艾的现场，毒贩就会立刻引爆炸弹，无论是否救到林小艾，爆炸都会发生。",
        "emotional_tone": "震撼、寒意、恍然大悟",
        "key_scenes": ["和线人秘密接头场景", "拿到毒贩的行动计划文档场景", "陆沉终于明白自己是爆炸触发点场景"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "当年的事",
        "core_event": "陆沉查到苏晚的父亲十年前也是刑警，当年为了阻止一场公交爆炸案，主动牺牲了自己，才避免了更大的伤亡，他终于明白苏晚为什么会做出这样的选择。",
        "emotional_tone": "心疼、理解、沉重",
        "key_scenes": ["陆沉查询苏父的旧案卷宗场景", "回忆苏晚曾经提过父亲的细节场景", "陆沉第一次对苏晚的选择产生共情场景"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "密室交锋",
        "core_event": "苏晚约陆沉到法医中心的解剖室拿之前的检验报告，两人在封闭的解剖室里展开高智商的交锋，苏晚话里有话暗示陆沉不要插手当晚的行动，陆沉也试探出她已经做好了同归于尽的准备。",
        "emotional_tone": "惊险、张力拉满、暗流汹涌",
        "key_scenes": ["解剖室单独对话场景", "两人互相试探话里有话场景", "苏晚故意展示手术刀暗示陆沉场景"]
      },
      {
        "chapter_number": 12,
        "chapter_title": "林小艾的证词",
        "core_event": "陆沉终于找到藏在出租屋的林小艾，拿到了她的证词和炸弹的位置信息，林小艾告诉他，毒贩在炸弹上装了面部识别装置，只要检测到陆沉的脸在现场一公里范围内，就会自动引爆。",
        "emotional_tone": "线索集齐、真相大白、沉重",
        "key_scenes": ["找到林小艾的藏身地场景", "录口供拿到证词场景", "得知炸弹触发条件的真相场景"]
      },
      {
        "chapter_number": 13,
        "chapter_title": "苏晚的计划",
        "core_event": "陆沉在苏晚的车里发现了她提前写好的认罪书和遗书，她计划杀了陆沉之后，立刻带着林小艾的证词去拆弹，然后主动自首，承担所有罪责，用自己的命换全城人的安全。",
        "emotional_tone": "心碎、感动、悲壮",
        "key_scenes": ["陆沉找到苏晚的遗书和认罪书场景", "阅读遗书内容场景", "陆沉终于明白苏晚的全部计划场景"]
      },
      {
        "chapter_number": 14,
        "chapter_title": "内鬼现身",
        "core_event": "陈默发现陆沉已经找到了林小艾，亲自带人过来灭口，陆沉和他正面交锋，拿到了陈默是内鬼的证据，但是也暴露了自己已经知道全部真相的事实。",
        "emotional_tone": "惊险、刺激、反转",
        "key_scenes": ["陈默带人围堵陆沉场景", "两人正面交锋摊牌场景", "陆沉拿到陈默犯罪证据场景"]
      },
      {
        "chapter_number": 15,
        "chapter_title": "摊牌边缘",
        "core_event": "苏晚也知道了陆沉已经查清了所有真相，她不再掩饰，直接和陆沉摊牌，告诉他如果他敢去救林小艾，她一定会杀了他，两人站在天台上面面相觑，距离23点还有3小时。",
        "emotional_tone": "悲壮、虐心、无奈",
        "key_scenes": ["天台摊牌场景", "苏晚含泪劝陆沉放弃场景", "两人回忆过往恋爱细节场景"]
      },
      {
        "chapter_number": 16,
        "chapter_title": "破局思路",
        "core_event": "陆沉一边稳住苏晚，一边和赵局秘密联系，商量出一个冒险的计划：他假装被苏晚杀死，让毒贩放松警惕，然后由赵局带队去拆弹，同时抓捕陈默和毒贩团伙。",
        "emotional_tone": "烧脑、充满希望、孤注一掷",
        "key_scenes": ["陆沉和赵局秘密通话场景", "推演计划的可行性场景", "准备假死所需的道具场景"]
      },
      {
        "chapter_number": 17,
        "chapter_title": "最后一小时",
        "core_event": "距离23点还有最后一小时，陆沉回到家，和苏晚一起吃了最后一顿晚饭，两人都没有提爆炸案的事，像普通情侣一样聊婚礼的细节，把最后的时间留给了彼此。",
        "emotional_tone": "温情、虐心、宿命感",
        "key_scenes": ["两人一起做最后一顿晚饭场景", "聊婚礼细节回忆过往场景", "倒计时数字不断跳动场景"]
      },
      {
        "chapter_number": 18,
        "chapter_title": "真相大白",
        "core_event": "吃完饭，陆沉主动告诉苏晚，他早就知道了所有真相，也知道她杀自己是为了阻止爆炸，他同意配合她的计划，但是希望她事后不要自首，好好活下去。",
        "emotional_tone": "震撼、感动、全员破防",
        "key_scenes": ["陆沉主动摊牌场景", "苏晚情绪崩溃痛哭场景", "两人达成共识准备执行计划场景"]
      }
    ],
    "turning_point": "陆沉得知全部真相：苏晚杀他不是因为私人恩怨，而是因为他是炸弹的触发点，只有他死了，毒贩才不会引爆炸弹，苏晚已经做好了杀他之后自首抵命的准备。"
  },
  "act_three": {
    "description": "第三幕（共6章，约3万字，占总篇幅25%）：倒计时进入最后阶段，陆沉和苏晚共同执行假死计划，成功阻止爆炸案，逮捕所有犯罪分子，最终两人都为了理想和责任，牺牲了自己的个人幸福，迎来符合D20模式的献祭结局。",
    "key_chapters": [
      {
        "chapter_number": 19,
        "chapter_title": "23点整",
        "core_event": "23点整，苏晚按照计划用提前准备好的空包弹“射杀”了陆沉，陈默在暗处监视，确认陆沉“死亡”，立刻通知毒贩不用引爆炸弹，赵局的人同时行动，抓捕陈默和所有毒贩成员。",
        "emotional_tone": "紧张、惊险、高潮迭起",
        "key_scenes": ["苏晚开枪射杀陆沉场景", "陈默确认陆沉死亡通知毒贩场景", "警方抓捕行动场景"]
      },
      {
        "chapter_number": 20,
        "chapter_title": "拆弹行动",
        "core_event": "拆弹组按照林小艾提供的位置找到炸弹，成功拆除，地铁1号线的乘客完全不知道自己刚刚躲过了一场灾难，爆炸案被成功阻止，没有任何人员伤亡。",
        "emotional_tone": "松一口气、欣慰、如释重负",
        "key_scenes": ["拆弹组拆除炸弹场景", "地铁正常运行场景", "赵局宣布行动成功场景"]
      },
      {
        "chapter_number": 21,
        "chapter_title": "自首",
        "core_event": "苏晚没有按照约定活下去，她主动到公安局自首，承认自己“杀害”了陆沉，愿意承担所有罪责，陆沉醒过来之后得知消息，立刻赶到警局要说明真相。",
        "emotional_tone": "意外、沉重、无奈",
        "key_scenes": ["苏晚主动到警局自首场景", "陆沉醒过来得知消息场景", "陆沉赶到警局要求撤销案件场景"]
      },
      {
        "chapter_number": 22,
        "chapter_title": "最后的选择",
        "core_event": "苏晚拒绝了陆沉的帮助，她告诉陆沉，只有她被定罪，毒贩的残余势力才不会来找林小艾的麻烦，也不会再有后续的报复行动，她愿意用自己的自由换永久的平安。",
        "emotional_tone": "悲壮、虐心、理想主义",
        "key_scenes": ["看守所会见场景", "苏晚说服陆沉接受她的选择场景", "两人隔着玻璃告别场景"]
      },
      {
        "chapter_number": 23,
        "chapter_title": "判决",
        "core_event": "法院公开审理此案，所有证据都显示苏晚是正当防卫（陆沉暗中修改了证据），苏晚最终被判处有期徒刑三年，缓刑三年，保留公职，调到基层当法医。",
        "emotional_tone": "遗憾、释然、符合预期",
        "key_scenes": ["法庭审判场景", "宣读判决书场景", "苏晚走出法庭场景"]
      },
      {
        "chapter_number": 24,
        "chapter_title": "献祭",
        "core_event": "陆沉和苏晚主动取消了婚礼，苏晚去了偏远的区县当法医，陆沉继续留在重案组当组长，两人都没有再谈恋爱，把一生都奉献给了警察事业，践行了入警时的誓言。",
        "emotional_tone": "平静、有力量、余韵悠长",
        "key_scenes": ["两人取消婚礼场景", "苏晚离开城市场景", "陆沉站在警局天台看着苏晚离开的方向场景"]
      }
    ],
    "turning_point": "爆炸案被成功阻止，没有任何平民伤亡，苏晚主动自首承担罪责，两人的个人幸福为公共利益做出了牺牲。"
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
